import React, {useCallback, useMemo, useRef, useState} from 'react';
import {
    View,
    Text,
    StyleSheet,
    SafeAreaView,
    Pressable,
    TextInput,
    Dimensions,
    FlatList,
    Platform,
    ActivityIndicator
} from 'react-native';
import {useDispatch, useSelector} from 'react-redux';
import {loadProductScreen} from '../../store/actions/post';
import {THEME} from '../../theme';
import {OneProduct} from '../../components/Catalog/Product/ProductCatd/OneProduct';
import {AntDesign} from '@expo/vector-icons';
import {IconLabelEbee} from '../../components/IconLabelEbee';
import {getTypeDevice} from '../../templateComponents/GetTypeDeviceSize/GetTypeDeviceSize';
import Fuse from 'fuse.js';

const normalizeText = (value) => String(value || '').toLowerCase().replace(/ё/g, 'е').trim();

export const SearchScreen = ({navigation}) => {
    const [query, setQuery] = useState('');
    const dispatch = useDispatch();
    const flatListRef = useRef(null);

    const allProduct = useSelector((state) => state.post.allProducts);
    const reloadedCatalog = useSelector((state) => state.post.reloadedCatalog);
    const deliveryAddress = useSelector((state) => state.post.adressSelect);
    const affiliateAddress = useSelector((state) => state.post.affiliateSelect);
    const typeDeliverySystem = useSelector((state) => state.post.typeDeliverySystem);

    const addressData = typeDeliverySystem ? deliveryAddress : affiliateAddress;
    const noneDeliveryText = typeDeliverySystem ? 'Нет доставки на Ваш адрес' : 'Не готовят на выбранной точке';

    const offCategorySet = useMemo(() => {
        const raw = typeDeliverySystem
            ? addressData?.OffCategoryData?.OffCategory
            : addressData?.JsonNoneCheck?.category_none;

        if (!raw) {
            return new Set();
        }

        const keys = typeof raw === 'object' ? Object.keys(raw) : [];
        return new Set(keys.map((id) => String(id)));
    }, [addressData, typeDeliverySystem]);

    const searchIndex = useMemo(() => {
        const out = [];

        Object.keys(allProduct || {}).forEach((categoryKey) => {
            const products = allProduct?.[categoryKey]?.ProductList || {};
            Object.keys(products).forEach((productId) => {
                const variants = products[productId] || [];
                variants.forEach((variant) => {
                    const title = String(variant?.title || '').trim();
                    const description = String(variant?.description || '').trim();
                    const ingredients = String(
                        variant?.ingredients || variant?.sostav || variant?.text_preview || ''
                    ).trim();

                    const image = String(variant?.img || '').trim();
                    const imageUrl = image.startsWith('http') ? image : `https:${image}`;

                    out.push({
                        ...variant,
                        id: productId,
                        img: imageUrl,
                        activeProduct: !offCategorySet.has(String(variant?.id_Category)),
                        searchTitle: normalizeText(title),
                        searchIngredients: normalizeText(ingredients),
                        searchText: normalizeText(`${title} ${ingredients} ${description}`)
                    });
                });
            });
        });

        return out;
    }, [allProduct, offCategorySet]);

    const fuse = useMemo(() => {
        if (!searchIndex.length) {
            return null;
        }
        return new Fuse(searchIndex, {
            keys: [
                {name: 'searchTitle', weight: 0.5},
                {name: 'searchIngredients', weight: 0.25},
                {name: 'searchText', weight: 0.25}
            ],
            threshold: 0.35,
            ignoreLocation: true,
            distance: 100,
            minMatchCharLength: 2,
            includeScore: true
        });
    }, [searchIndex]);

    const results = useMemo(() => {
        const q = normalizeText(query);
        if (!q) {
            return [...searchIndex].sort((a, b) => Number(b.activeProduct) - Number(a.activeProduct));
        }

        if (fuse) {
            return fuse
                .search(q)
                .sort((a, b) => {
                    if (b.item.activeProduct !== a.item.activeProduct) {
                        return Number(b.item.activeProduct) - Number(a.item.activeProduct);
                    }
                    return (a.score || 0) - (b.score || 0);
                })
                .map((entry) => entry.item);
        }

        return searchIndex
            .filter((item) => item.searchText.includes(q))
            .sort((a, b) => Number(b.activeProduct) - Number(a.activeProduct));
    }, [query, searchIndex, fuse]);

    const openProductHandler = (product) => {
        if (typeof window !== 'undefined') {
            window.location.hash = 'Product';
        }
        navigation.navigate('Product', {
            productId: product.id,
            title: product.title,
            booked: product.booked,
            productData: product
        });
    };

    const loadProductScreenHandler = useCallback((product) => {
        dispatch(loadProductScreen(product));
    }, [dispatch]);

    const clearSearch = () => {
        setQuery('');
        if (flatListRef.current) {
            flatListRef.current.scrollToOffset({animated: false, offset: 0});
        }
    };

    const isLoading = reloadedCatalog || addressData === null;

    return (
        <View style={styles.center}>
            <View style={styles.searchBar}>
                {Platform.OS === 'android' ? (
                    <Pressable style={styles.backButton} onPress={() => navigation.goBack()}>
                        <IconLabelEbee name={'arrow-back'} size={24} color={THEME.MAIN_COLOR} typeIcon={'Ionicons'} />
                    </Pressable>
                ) : null}

                <TextInput
                    style={styles.input}
                    value={query}
                    onChangeText={setQuery}
                    placeholder={'Поиск по товарам...'}
                    autoCorrect={false}
                    autoCapitalize={'none'}
                />

                <Pressable style={styles.clearButton} onPress={clearSearch}>
                    <IconLabelEbee name={'close'} size={24} color={THEME.MAIN_COLOR} typeIcon={'Ionicons'} />
                </Pressable>
            </View>

            {isLoading ? (
                <SafeAreaView style={styles.centerState}>
                    {addressData === null ? (
                        <>
                            <AntDesign name={'exclamationcircleo'} size={72} color={THEME.MAIN_COLOR} />
                            <Text style={styles.centerText}>{'\n'}Выберите адрес {'\n'}для доставки или самовывоза</Text>
                        </>
                    ) : (
                        <ActivityIndicator color={THEME.MAIN_COLOR} />
                    )}
                </SafeAreaView>
            ) : results.length > 0 ? (
                <FlatList
                    ref={flatListRef}
                    data={results}
                    showsVerticalScrollIndicator={false}
                    numColumns={getTypeDevice(Dimensions.get('window').width, Dimensions.get('window').height) === false ? 2 : 1}
                    keyExtractor={(product) => `${product.id}_${product.type_product}`}
                    columnWrapperStyle={
                        getTypeDevice(Dimensions.get('window').width, Dimensions.get('window').height) === false ? {width: '100%'} : null
                    }
                    renderItem={({item}) =>
                        item.activeProduct ? (
                            <OneProduct
                                product={item}
                                onOpen={openProductHandler}
                                onOpenProduct={loadProductScreenHandler}
                            />
                        ) : (
                            <View>
                                <View style={styles.disabledOverlay}>
                                    <Text style={styles.disabledText}>{noneDeliveryText}</Text>
                                </View>
                                <OneProduct product={item} onOpen={() => {}} onOpenProduct={() => {}} />
                            </View>
                        )
                    }
                    style={styles.list}
                />
            ) : (
                <SafeAreaView style={styles.centerState}>
                    <AntDesign name={'search1'} size={72} color={THEME.MAIN_COLOR} />
                    <Text style={styles.noItems}>{query.length > 0 ? 'Ничего не найдено' : 'Введите запрос'}</Text>
                </SafeAreaView>
            )}
        </View>
    );
};

const styles = StyleSheet.create({
    center: {
        flex: 1,
        width: '100%',
        alignItems: 'center',
        justifyContent: 'flex-start'
    },
    searchBar: {
        width: '100%',
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#ffffff',
        borderBottomWidth: 1,
        borderBottomColor: THEME.BORDER_COLOR_DEFAULT
    },
    backButton: {
        width: '10%',
        alignItems: 'center',
        justifyContent: 'center',
        borderRightWidth: 1,
        borderRightColor: THEME.BORDER_COLOR_DEFAULT,
        paddingVertical: 10
    },
    input: {
        flex: 1,
        borderWidth: 0,
        paddingVertical: 12,
        paddingHorizontal: 10,
        color: THEME.TEXT_COLOR_TABS_MENU_DEFAULT,
        backgroundColor: '#ffffff'
    },
    clearButton: {
        width: '10%',
        alignItems: 'center',
        justifyContent: 'center'
    },
    list: {
        width: '100%',
        height: Dimensions.get('window').height - Dimensions.get('window').height / 5
    },
    centerState: {
        width: '100%',
        height: Dimensions.get('window').height * 0.55,
        alignItems: 'center',
        justifyContent: 'center'
    },
    centerText: {
        textAlign: 'center'
    },
    noItems: {
        fontFamily: 'open-regular',
        textAlign: 'center',
        marginVertical: 10,
        fontSize: 18,
        minWidth: 150
    },
    disabledOverlay: {
        backgroundColor: 'rgba(255,250,255,0.8)',
        zIndex: 99,
        position: 'absolute',
        width: '100%',
        height: '100%',
        justifyContent: 'center',
        alignItems: 'center',
        flexDirection: 'row'
    },
    disabledText: {
        color: THEME.MAIN_COLOR,
        backgroundColor: '#ffffff',
        paddingVertical: '2%',
        paddingHorizontal: '5%',
        borderRadius: THEME.BORDER_RADIUS_DEFAULT
    }
});
